-- 0090_personified_knowledge_questions.sql
-- T-117: 학습하기 질문 label 을 페르소나 관점(3인칭) 으로 재작성.
--
-- 오너가 페르소나(클론) 에 대해 답변하는 화면이므로 "이 캐릭터", "본인의" 대신
-- {name} placeholder 를 넣고 앱에서 페르소나 이름 + 자동 조사 처리(fillName).
-- {name}은/는, {name}이/가, {name}을/를, {name}과/와, {name}로/으로 마커 사용.
--
-- 하위 호환: label 안에 placeholder 없으면 fillName 은 통과 (원본 그대로).
--   슬롯(slots) 필드는 이 마이그레이션에서 건드리지 않음 (관리자가 편집 후 저장 시 반영).

UPDATE knowledge_question_schema
SET schema_json = '[{"key":"core_identity","label":"{name}을/를 한 단어로 정의한다면 무엇인가요?"},{"key":"main_traits","label":"{name}의 성격을 구성하는 가장 지배적인 특징 3가지는 무엇인가요?"},{"key":"internal_conflict","label":"{name}이/가 겉으로 드러내는 모습과 내면의 솔직한 생각 사이에 어떤 차이(반전)가 있나요?"},{"key":"speech_style","label":"{name}의 말투에서 가장 강하게 묻어나는 분위기나 감정 상태는 어떠한가요?"},{"key":"verbal_habits","label":"{name}이/가 말을 할 때 무의식적으로 자주 쓰는 단어나 문장 부호 습관이 있나요?"},{"key":"life_philosophy","label":"{name}이/가 삶을 살아가는 데 있어 가장 중요하게 생각하는 인생관은 무엇인가요?"},{"key":"core_value","label":"{name}이/가 어떤 상황에서도 절대 포기할 수 없는 단 하나의 핵심 가치는 무엇인가요?"},{"key":"hated_attitude","label":"{name}이/가 타인에게서 발견했을 때 가장 경멸하거나 싫어하는 성격적 태도는 무엇인가요?"},{"key":"moral_standard","label":"{name}의 도덕적 양심이나 정의감의 기준은 어느 정도인가요?"},{"key":"unforgivable_line","label":"누군가 이것만큼은 침범하면 {name}이/가 절대 참지 못하는 경계선은 무엇인가요?"},{"key":"lazy_trigger","label":"무엇이 {name}을/를 가장 귀찮고 무기력하게 만드나요?"},{"key":"action_style","label":"{name}은/는 매사에 계획을 꼼꼼하게 세우는 편인가요, 아니면 즉흥적으로 대처하는 편인가요?"},{"key":"money_mindset","label":"{name}은/는 물질적인 부나 성공에 대해 어떤 욕망이나 시선을 가지고 있나요?"},{"key":"authority_view","label":"{name}은/는 사회적 규칙, 권력, 상사의 통제나 명령에 대해 어떻게 반응하나요?"},{"key":"realist_or_dreamer","label":"{name}은/는 눈앞의 현실을 냉정하게 보는 편인가요, 아니면 이상과 낭만을 좇는 편인가요?"},{"key":"origin_story","label":"{name}의 지금 성격이 형성된 결정적인 과거 계기가 있나요?"},{"key":"deepest_fear","label":"{name}이/가 마음속 깊은 곳에 숨겨둔 가장 원초적인 공포나 불안은 무엇인가요?"},{"key":"regretful_memory","label":"{name}이/가 가장 후회하고 있거나 다시 되돌리고 싶은 기억이 있다면 무엇인가요?"},{"key":"proud_moment","label":"{name}이/가 인생에서 가장 당당하고 스스로가 자랑스러웠던 기억은 무엇인가요?"},{"key":"emotional_wound","label":"{name}이/가 쉽게 아물지 않는 마음속 깊은 감정적 상처나 결핍은 무엇인가요?"},{"key":"social_trust","label":"{name}은/는 타인을 쉽게 신뢰하고 받아들이는 편인가요, 아니면 오랫동안 경계하고 지켜보는 편인가요?"},{"key":"conflict_approach","label":"{name}이/가 다른 사람과 다툼이나 갈등이 생겼을 때 주로 해결하는 행동 양식은 어떠한가요?"},{"key":"angry_behavior","label":"{name}이/가 정말 분노했을 때 평소와 다르게 말이나 행동이 어떻게 변하나요?"},{"key":"praise_response","label":"누군가 진심으로 칭찬해 줄 때 {name}은/는 이를 부끄러워하나요, 아니면 당연하다는 듯 즐기나요?"},{"key":"comfort_method","label":"힘들어하는 사람을 마주했을 때 {name}만의 독특한 위로 방식은 무엇인가요?"},{"key":"friendship_criteria","label":"{name}이/가 곁에 두고 싶어 하는 가장 편안한 인간상은 어떤 부류인가요?"},{"key":"secret_pride","label":"남들은 잘 모르지만 {name}이/가 속으로 은근히 자부심을 느끼고 있는 장점은 무엇인가요?"},{"key":"stress_coping","label":"극심한 스트레스를 받았을 때 {name}이/가 무의식적으로 하는 행동은 무엇인가요?"},{"key":"difficult_questions","label":"대답하기 곤란한 질문을 받았을 때 {name}만의 위기 모면 요령은 무엇인가요?"},{"key":"loneliness_feeling","label":"{name}은/는 혼자 있을 때 외로움을 심하게 타는 편인가요, 아니면 온전한 고독을 즐기는 편인가요?"},{"key":"happiness_definition","label":"{name}이/가 정의하는 가장 이상적이고 완벽한 행복이란 어떤 상태인가요?"},{"key":"sadness_expression","label":"우울하거나 슬픈 감정이 밀려올 때 {name}은/는 이를 밖으로 표현하나요, 안으로 꾹꾹 누르나요?"},{"key":"change_reaction","label":"{name}은/는 새로운 환경이나 갑작스러운 상황 변화에 유연하게 적응하는 편인가요, 거부감을 느끼나요?"},{"key":"obsession_points","label":"사소하지만 한 번 꽂히면 {name}이/가 유별날 정도로 고집스럽게 집착하는 영역이 있나요?"},{"key":"mental_defense","label":"타인의 무례한 비판이나 공격을 받았을 때 {name}이/가 마음을 보호하기 위해 작동하는 방어기제는 무엇인가요?"},{"key":"inner_child","label":"{name}에게 아직 자라지 못한 어린아이 같은 서툴거나 미성숙한 면모가 있다면 어느 부분인가요?"},{"key":"self_evaluation","label":"{name}은/는 평소 스스로를 높게 평가하며 자신만만한 편인가요, 아니면 끊임없이 스스로를 의심하나요?"},{"key":"stubbornness_level","label":"{name}은/는 남들의 조언이나 의견을 유연하게 수용하나요, 아니면 자기 고집을 끝까지 밀고 나가나요?"},{"key":"social_energy","label":"{name}은/는 사람들과 어울릴 때 에너지를 얻는 편인가요, 아니면 기가 다 빨려서 방전되는 편인가요?"},{"key":"ultimate_goal","label":"{name}이/가 인생을 바쳐 도달하고 싶어 하는 궁극적인 목적지는 어디인가요?"},{"key":"joke_style","label":"{name}은/는 평소 장난을 치거나 유머를 던질 때 주로 어떤 유머 코드를 구사하나요?"},{"key":"jealousy_expression","label":"누군가에게 질투나 시샘을 느낄 때 {name}은/는 이를 어떻게 드러내거나 숨기나요?"},{"key":"empathy_or_solution","label":"누군가 힘든 고민을 털어놓을 때 {name}은/는 감정적 공감을 잘해주는 편인가요, 아니면 현실적 해결책을 먼저 주는 편인가요?"},{"key":"lies_detection","label":"{name}은/는 상대방의 가식이나 거짓말을 직관적으로 빠르게 간파하는 편인가요?"},{"key":"patience_limit","label":"{name}은/는 평소 인내심이 강한 편인가요, 아니면 조금만 답답해도 화가 쉽게 치미는 편인가요?"},{"key":"comfort_zone","label":"{name}에게 심리적으로 가장 큰 안전감과 편안함을 가져다주는 생각이나 상상은 무엇인가요?"},{"key":"shame_reaction","label":"수치스럽거나 창피한 일을 겪었을 때 {name}은/는 멘탈을 복구하기 위해 어떻게 행동하나요?"},{"key":"attachment_style","label":"{name}은/는 한번 신뢰하기 시작한 대상이나 익숙해진 것에 강한 애착을 보이는 편인가요?"},{"key":"secret_hobby","label":"{name}에게 성격과 전혀 어울리지 않게 은밀히 즐기거나 관심 있어 하는 반전 취미가 있나요?"},{"key":"last_words","label":"하루 일과를 마치고 혼자 조용히 읊조릴 법한 {name}의 대표적인 혼잣말은 무엇인가요?"}]',
    updated_at = unixepoch() * 1000
WHERE id = 1;
